(() => {
  'use strict';
  const C=window.DungeonCore,$=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');
  const SAVE='yuusha-afterhours-v1',SOUND='yuusha-afterhours-sound';
  let game=C.newGame(),tool='broom',hover=null,keyboardCell=[2,4],history=[],particles=[],speed=1,paused=false,active=false,sound=false,audio=null,toastTimer,modalPreviousFocus=null,frameTime=0,lastUI=0,saveFailure=false;
  let worker={x:3,y:6,tx:3,ty:6};
  let saved=null;
  try{const raw=localStorage.getItem(SAVE);if(raw){const parsed=JSON.parse(raw);if(C.validSave(parsed))saved=parsed;}sound=localStorage.getItem(SOUND)==='yes';}catch{}
  const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pos=(x,y)=>[52+x*54+27,32+y*52+26];
  const at=(px,py)=>[Math.floor((px-52)/54),Math.floor((py-32)/52)];
  const average=()=>game.reports.length?game.reports.reduce((a,r)=>a+r.rating,0)/game.reports.length:0;
  function save(){try{localStorage.setItem(SAVE,JSON.stringify(game));saved=JSON.parse(JSON.stringify(game));$('saveStatus').textContent='◇ このブラウザに自動セーブ';}catch{if(!saveFailure){toast('自動セーブが使えません。この画面を閉じずに遊んでください',true);saveFailure=true;}$('saveStatus').textContent='自動セーブ不可 · この画面で続けて遊べます';}}
  function toast(message,error=false){$('toast').textContent=message;$('toast').classList.toggle('error',error);$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2400);}
  function tone(kind){if(!sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const now=audio.currentTime;const notes=kind==='clean'?[650,900]:kind==='build'?[220,330,440]:kind==='report'?[330,440,550,660]:[350];notes.forEach((hz,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=hz;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(0,now+i*.055);g.gain.linearRampToValueAtTime(.065,now+i*.055+.01);g.gain.exponentialRampToValueAtTime(.001,now+i*.055+.16);o.start(now+i*.055);o.stop(now+i*.055+.18);});}catch{}}
  function showModal(html){if($('modalBackdrop').hidden)modalPreviousFocus=document.activeElement;$('modal').innerHTML=html;$('modalBackdrop').hidden=false;$('tooltip').hidden=true;requestAnimationFrame(()=>$('modal').focus());}
  function closeModal(){$('modalBackdrop').hidden=true;if(modalPreviousFocus?.isConnected)modalPreviousFocus.focus();}
  const welcomeArt=`<svg class="welcome-art" viewBox="0 0 430 135" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><ellipse cx="215" cy="118" rx="162" ry="9" fill="#102126"/><path d="M62 108V54L105 33L147 54V108Z" fill="#3f514b"/><path d="M76 108V65L104 49L132 65V108" fill="#15272c"/><path d="M85 108V73Q104 39 124 73V108" fill="#243b36"/><path d="M95 80L101 87L114 69" fill="none" stroke="#abd3a7" stroke-width="3"/><path d="M61 52L103 30L149 52" fill="none" stroke="#738275" stroke-width="4"/><path d="M299 107V83Q299 60 326 60Q353 60 353 83V107Z" fill="#bb8751" stroke="#342d26" stroke-width="4"/><path d="M300 84H353M311 65V106M342 65V106" stroke="#e4bd74" stroke-width="5"/><rect x="320" y="80" width="12" height="15" rx="2" fill="#edd198"/><ellipse cx="208" cy="111" rx="29" ry="7" fill="#102126"/><path d="M189 101L185 119H202L206 101M215 102L219 119H235L228 99" fill="#b7996a"/><path d="M189 76Q210 65 229 76L237 104H182Z" fill="#8fbb93"/><rect x="197" y="48" width="27" height="31" rx="9" fill="#dec298"/><path d="M187 58Q211 21 233 58Z" fill="#739575"/><rect x="205" y="60" width="3" height="5" fill="#243732"/><rect x="217" y="60" width="3" height="5" fill="#243732"/><path d="M237 85L262 31" stroke="#bd9461" stroke-width="5"/><path d="M247 64L264 73L246 115L222 103Z" fill="#e0c489"/><path d="M239 82L231 106M248 87L240 110" stroke="#b49c66" stroke-width="2"/><path d="M166 53L170 43L174 53L184 57L174 61L170 71L166 61L156 57Z" fill="#d8bf7d"/><path d="M278 91L281 85L284 91L290 94L284 97L281 103L278 97L272 94Z" fill="#9ecc9b"/></svg>`;
  function welcome(){showModal(`${welcomeArt}<span class="eyebrow">DUNGEON AFTER HOURS</span><h2 id="modalTitle">勇者のあとしまつ</h2><p class="intro">勇者は世界を救った。<br><strong>床と壁のことは、何も考えていなかった。</strong><br>あなたは魔王軍の清掃員。7日間で、この迷宮を「また来たい場所」に変えよう。</p><div class="steps"><div><b>01</b><strong>拾って、きれいに。</strong><p>落とし物を回収して<br>お金と資材に。</p></div><div><b>02</b><strong>ちょっと、いたずら。</strong><p>罠・宝箱・ベンチで<br>自分だけの順路を。</p></div><div><b>03</b><strong>夜は、見守る。</strong><p>冒険者の反応が<br>明日の売上になる。</p></div></div><button class="primary" id="welcomeStart">${saved?'つづきから働く':'開店準備をはじめる'}　→</button><p class="modal-note">マウス・タッチ・キーボード対応 ／ 準備中の時間制限なし<br>1プレイ約15分 · 自動セーブ</p>`);$('welcomeStart').onclick=()=>{if(saved)game=saved;active=true;closeModal();update();if(game.phase==='report')report();if(game.phase==='ending')ending();save();};}
  function help(){showModal(`<span class="eyebrow">STAFF HANDBOOK</span><h2 id="modalTitle">小さな迷宮の、働き方。</h2><ol class="help-list"><li><b>ほうきで掃除。</b> 光る瓦礫・剣・木片・粘液をクリックすると、行動力1で資材1と3Gを回収します。すべて拾えば営業後に15Gのボーナス。</li><li><b>点線の順路に設備を設置。</b> 道具を選び、空いている通路をクリック。お金・資材・行動力1を使います。置き間違いは「ひとつ戻す」で取り消せます。</li><li><b>怖さと、おもてなしを。</b> 粘液の3マス以内にトゲ罠を置くと連携。強い罠ばかりだとお客さまが途中で帰るので、休憩ベンチとお宝箱も大切です。同じ設備を増やすより種類を増やすと高評価。</li><li><b>準備ができたら夜の営業へ。</b> 行動力が残っていても開店できます。営業中は一時停止と4倍速までの切り替えが可能です。</li><li><b>7日間の評判で結末が変わります。</b> 設備と所持金は翌日へ引き継ぎ。5日目からはお客さまが4人に増えます。</li></ol><p class="modal-note">1–7：道具切替 ／ 矢印：マス移動 ／ Enter：使用<br>Ctrl・⌘＋Z：取り消し ／ Space：営業中の一時停止<br>音は右上の♪からオンにできます。</p><button class="primary" id="helpClose">仕事に戻る　→</button>`);$('helpClose').onclick=closeModal;}
  function report(){const r=game.lastReport;showModal(`<span class="eyebrow">DAY ${String(r.day).padStart(2,'0')} · 営業日報</span><h2 id="modalTitle">本日も、おつかれさま。</h2><div class="report-score"><strong>${r.rating.toFixed(1)}</strong><div><span>${'★'.repeat(Math.round(r.rating))}${'☆'.repeat(5-Math.round(r.rating))}</span><small>${r.finished} / ${r.count}人が完走 · 清掃率 ${r.clean}%</small></div></div><div class="account"><div>売上<strong>＋${r.revenue}G</strong></div><div>清掃ボーナス<strong>＋${r.bonus}G</strong></div><div>維持費<strong>−${r.fee}G</strong></div></div>${r.reviews.map(v=>`<div class="review"><div><b>${esc(v.name)}</b><span>★ ${v.stars.toFixed(1)}</span></div><p>「${esc(v.text)}」</p></div>`).join('')}<button class="primary" id="nextDay">${r.day===7?'7日間の成果を見る':'翌朝へ。あと'+(7-r.day)+'日'}　→</button><p class="modal-note">本日の利益 ＋${r.profit}G · 設備は明日も使えます。</p>`);$('nextDay').onclick=()=>{C.nextDay(game);history=[];tool='broom';save();update();if(game.phase==='ending')ending();else{closeModal();toast('おはようございます。今日も、あとしまつ。');}};tone('report');}
  function ending(){const avg=average(),title=avg>=4?'伝説の、また来たい迷宮。':avg>=3?'こもれび迷宮、営業再開。':'明日も、ほうきを持って。',body=avg>=4?'勇者は出口で振り返った。「次は、仲間を連れてくるよ」。壊すことしか知らなかった迷宮に、帰ってくる理由ができました。':avg>=3?'魔王さまの閉鎖命令は撤回されました。床はきれいに、宝箱には夢が。あなたの迷宮に、次の予約が届いています。':'完璧な一週間ではなかったけれど、あなたが拾ったものは確かに残りました。次こそ、あの勇者に星5を付けさせましょう。';showModal(`${welcomeArt}<span class="eyebrow">7 DAYS LATER · ${avg>=4?'MASTER KEEPER':avg>=3?'DUNGEON REOPENED':'KEEP SWEEPING'}</span><h2 id="modalTitle">${title}</h2><p class="intro">${body}</p><div class="account"><div>7日間の評判<strong>★ ${avg.toFixed(1)}</strong></div><div>迎えた冒険者<strong>${game.totalVisitors}人</strong></div><div>拾った落とし物<strong>${game.totalCleaned}個</strong></div></div><div class="ending-days">${game.reports.map(r=>`<div style="height:${r.rating/5*75}px"><span>${r.rating.toFixed(1)}</span></div>`).join('')}</div><div class="ending-caption"><span>DAY 01</span><span>DAY 07</span></div><button class="primary" id="playAgain">新しい迷宮で、もう一週間　→</button><p class="modal-note">遊んでくれて、ありがとう。<br>勇者のあとしまつ — 企画・文章・描画・音・コードまでオリジナル制作。</p>`);$('playAgain').onclick=reset;}
  function reset(){game=C.newGame();history=[];tool='broom';particles=[];speed=1;paused=false;active=true;worker={x:3,y:6,tx:3,ty:6};closeModal();save();update();}
  function confirmReset(){showModal(`<span class="eyebrow">NEW SHIFT</span><h2 id="modalTitle">1日目からやり直す？</h2><p class="intro">いまの進行を消して、新しい迷宮で始めます。</p><button class="primary" id="resetYes">最初からはじめる</button><button class="secondary" id="resetNo">今の仕事を続ける</button>`);$('resetYes').onclick=reset;$('resetNo').onclick=()=>{closeModal();if(game.phase==='report')report();else if(game.phase==='ending')ending();};}
  function update(){
    $('day').textContent=String(game.day).padStart(2,'0');$('gold').textContent=game.gold;$('material').textContent=game.material;$('energy').textContent=game.energy;$('maxenergy').textContent='/ '+game.maxEnergy;$('rating').textContent=average()?average().toFixed(1):'—';
    const night=game.phase==='night';$('phase').textContent=night?'夜の営業':game.phase==='prep'?'開店準備':'営業終了';$('mapBadge').innerHTML='<i></i> '+(night?'営業中 · '+C.DAYS[game.day-1][2]:'準備中 · 時間制限なし');
    document.querySelector('.tools-panel').hidden=night;$('nightLog').hidden=!night;$('startNight').hidden=night;$('nightOverlay').hidden=!night;$('startNight').disabled=game.phase!=='prep';
    $('undo').disabled=!history.length||game.phase!=='prep';$('cleanText').textContent=game.cleaned+' / '+game.initialDirt;$('cleanBar').style.width=(C.cleanliness(game)*100)+'%';$('cleanBonus').textContent=C.cleanliness(game)===1?'ぴかぴか！ 営業後の＋15Gボーナス確定':'全回収で営業後に＋15G';
    $('toolDetail').textContent=C.ITEMS[tool].detail;document.querySelectorAll('.tool').forEach(el=>{const chosen=el.dataset.tool===tool;el.classList.toggle('selected',chosen);el.setAttribute('aria-pressed',String(chosen));});
    $('mapHint').textContent=night?'冒険者の反応を見て、明日の改装を考えよう。':tool==='broom'?'光る落とし物をクリックして、あとしまつ。':tool==='remove'?'回収したい設備をクリック。':'点線の通路の空いているマスに設置。';
    $('upgrade').disabled=game.upgrade>=3||game.gold<40+game.upgrade*25||game.phase!=='prep';$('upgrade').innerHTML='<span>↑ 作業かばんを拡張<small>行動力の上限 ＋4</small></span><b>'+(game.upgrade>=3?'MAX':(40+game.upgrade*25)+'G')+'</b>';
    $('briefTitle').textContent=C.DAYS[game.day-1][0];$('briefText').textContent=C.DAYS[game.day-1][1];$('reservation').textContent=C.DAYS[game.day-1][2];$('guestCount').textContent=(game.day>=5?4:3)+'名様';
    $('sound').innerHTML='♪<span>'+(sound?'ON':'OFF')+'</span>';$('sound').setAttribute('aria-label',sound?'効果音をオフ':'効果音をオン');
    $('speed').textContent='速度 ×'+speed;$('pause').textContent=paused?'再開':'一時停止';
    if(night)updateNight();
  }
  function updateNight(){$('visitorCount').textContent=game.heroes.filter(h=>h.done).length+' / '+game.heroes.length+' 探索終了';$('heroCards').innerHTML=game.heroes.map(h=>`<div class="hero-card"><div><b>${esc(h.name)}</b><span>${h.done?(h.escaped?'途中帰宅':'★ '+h.rating.toFixed(1)):h.pos<0?'入場待ち':Math.ceil(h.hp)+' / '+h.maxHp}</span></div><div class="hp"><i style="width:${h.hp/h.maxHp*100}%;background:${h.hp/h.maxHp<.3?'#e99885':'#a8d5ae'}"></i></div></div>`).join('');$('eventLog').innerHTML=game.events.slice(0,7).map(e=>`<div class="${e.type}">${esc(e.text)}</div>`).join('');}
  function choose(kind){if(game.phase!=='prep')return;tool=kind;update();}
  function action(x,y){if(!active||!$('modalBackdrop').hidden||game.phase!=='prep')return;$('tooltip').hidden=true;const snapshot=JSON.stringify(game),result=C.act(game,x,y,tool);if(!result.ok){toast(result.message,true);return;}history.push(snapshot);if(history.length>30)history.shift();const [px,py]=pos(x,y);for(let i=0;i<14;i++)particles.push({x:px,y:py,vx:(Math.random()-.5)*90,vy:-30-Math.random()*65,life:.5+Math.random()*.4,color:result.effect==='clean'?'#c4e7b4':'#e6c17d'});worker.tx=x;worker.ty=y;toast(result.message);tone(result.effect);save();update();}
  function undo(){if(!history.length||game.phase!=='prep')return;game=JSON.parse(history.pop());save();update();toast('ひとつ前の状態に戻しました');}
  Object.entries(C.ITEMS).forEach(([id,item])=>{const button=document.createElement('button');button.className='tool';button.dataset.tool=id;button.setAttribute('aria-pressed',String(id===tool));button.innerHTML=`<canvas class="glyph" width="64" height="56" aria-hidden="true"></canvas><span class="tool-name">${item.name}<span class="tool-cost">${id==='broom'?'回収 ＋3G・資材1':id==='remove'?'費用の半分を回収':item.cost+'G · 資材'+item.material}</span></span><kbd>${item.key}</kbd>`;button.onclick=()=>choose(id);$('tools').appendChild(button);const icon=button.querySelector('canvas').getContext('2d');icon.translate(32,31);drawIcon(icon,id,1,0);});
  $('startNight').onclick=()=>{if(game.phase!=='prep')return;const begin=()=>{closeModal();save();C.startNight(game);history=[];paused=false;speed=1;update();tone('build');};if(!Object.keys(game.devices).length){showModal(`<span class="eyebrow">OPEN THE DOORS?</span><h2 id="modalTitle">設備はまだ、ありません。</h2><p class="intro">このままでも営業できますが、罠と宝箱を置くと、冒険をもっと楽しんでもらえます。</p><button class="primary" id="prepareMore">もう少し準備する</button><button class="secondary" id="openAnyway">このまま営業する</button>`);$('prepareMore').onclick=closeModal;$('openAnyway').onclick=begin;}else begin();};
  $('undo').onclick=undo;$('upgrade').onclick=()=>{const before=JSON.stringify(game);if(C.upgrade(game)){history.push(before);save();update();tone('build');toast('かばんを拡張！ 今日から行動力＋4');}};
  $('help').onclick=help;$('brand').onclick=e=>{e.preventDefault();help();};$('restart').onclick=confirmReset;
  $('sound').onclick=()=>{sound=!sound;try{localStorage.setItem(SOUND,sound?'yes':'no');}catch{}tone('clean');update();};
  $('speed').onclick=()=>{speed=speed===1?2:speed===2?4:1;update();};$('pause').onclick=()=>{paused=!paused;update();};
  $('zoomMap').onclick=()=>{const zoom=$('canvasWrap').classList.toggle('zoomed');$('zoomMap').textContent=zoom?'全体 −':'拡大 ＋';$('zoomMap').setAttribute('aria-pressed',String(zoom));$('tooltip').hidden=true;if(zoom)toast('地図を横にスクロールできます');};
  function pointer(e){const r=canvas.getBoundingClientRect();return{px:(e.clientX-r.left)*canvas.width/r.width,py:(e.clientY-r.top)*canvas.height/r.height,r};}
  canvas.addEventListener('pointermove',e=>{const p=pointer(e);hover=at(p.px,p.py);if(game.phase!=='prep'||!active||!$('modalBackdrop').hidden)return;const k=C.key(...hover);const label=game.debris[k]?({rubble:'崩れた石材',sword:'勇者の忘れた剣',spill:'こぼれた粘液',wood:'割れた木材'}[game.debris[k]]+' · ほうきで回収'):game.devices[k]?C.ITEMS[game.devices[k]].name:C.ROUTE.slice(2,-1).some(t=>t[0]===hover[0]&&t[1]===hover[1])?'設備を置ける通路':null;$('tooltip').hidden=!label;if(label){$('tooltip').textContent=label;$('tooltip').style.left=Math.min(e.clientX-p.r.left+14,p.r.width-220)+'px';$('tooltip').style.top=Math.max(5,e.clientY-p.r.top-43)+'px';}});
  canvas.addEventListener('pointerleave',()=>{hover=null;$('tooltip').hidden=true;});
  canvas.addEventListener('click',e=>{const p=pointer(e);const cell=at(p.px,p.py);keyboardCell=cell;action(...cell);});
  document.addEventListener('keydown',e=>{
    if(!$('modalBackdrop').hidden){if(e.key==='Tab'){const els=[...$('modal').querySelectorAll('button,a,[tabindex="0"]')].filter(x=>!x.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('modal'))){e.preventDefault();first?.focus();}}return;}
    if(!active)return;
    if(/^[1-7]$/.test(e.key)){choose(Object.keys(C.ITEMS)[Number(e.key)-1]);return;}
    if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo();}
    if(e.code==='Space'&&game.phase==='night'){e.preventDefault();paused=!paused;update();}
    if(document.activeElement===canvas){if(e.key.startsWith('Arrow')){e.preventDefault();keyboardCell[0]=Math.max(0,Math.min(17,keyboardCell[0]+(e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0)));keyboardCell[1]=Math.max(0,Math.min(9,keyboardCell[1]+(e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0)));hover=[...keyboardCell];}if(e.key==='Enter'){e.preventDefault();action(...keyboardCell);}}
  });
  function rr(c,x,y,w,h,r,fill,stroke){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.lineWidth=1;c.stroke();}}
  function ellipse(c,x,y,rx,ry,color){c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill();}
  function line(c,points,color,width=2){c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.stroke();}
  function poly(c,points,color){c.fillStyle=color;c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fill();}
  function drawIcon(c,kind,scale=1,time=0){c.save();c.scale(scale,scale);ellipse(c,0,12,21,7,'#00000035');
    if(kind==='broom'){line(c,[[12,-24],[-7,8]],'#bd9461',5);poly(c,[[-11,-1],[4,8],[-9,23],[-25,13]],'#e5ca8b');line(c,[[-14,6],[-20,15]],'#b4955a',2);line(c,[[-8,10],[-14,19]],'#b4955a',2);}
    if(kind==='spikes'){rr(c,-21,1,42,17,3,'#414c4a','#87928a');for(let i=0;i<3;i++){poly(c,[[-18+i*13,10],[-12+i*13,-14],[-5+i*13,10]],'#cbd7c5');poly(c,[[-12+i*13,-14],[-12+i*13,10],[-5+i*13,10]],'#7d948c');}}
    if(kind==='slime'){ellipse(c,0,10,24,10,'#53886b');c.fillStyle='#9ccb8b';c.beginPath();c.moveTo(-21,8);c.quadraticCurveTo(-15,-25,0,-13+Math.sin(time*2)*2);c.quadraticCurveTo(19,-24,22,10);c.quadraticCurveTo(1,22,-21,8);c.fill();ellipse(c,-7,0,2,3,'#254740');ellipse(c,7,0,2,3,'#254740');ellipse(c,-11,-8,4,2,'#d5e8b5');line(c,[[-3,7],[3,7]],'#42654e',1.5);}
    if(kind==='treasure'||kind==='mimic'){rr(c,-21,-11,42,30,5,'#9e6e40','#483c30');rr(c,-21,-15,42,20,7,kind==='mimic'?'#966354':'#c39250');line(c,[[-20,4],[20,4]],'#4b332c',3);line(c,[[-13,-12],[-13,18]],'#dfbd77',4);line(c,[[13,-12],[13,18]],'#dfbd77',4);rr(c,-4,0,8,10,1,'#e8cf8e');if(kind==='mimic'){rr(c,-15,0,30,10,2,'#392a2e');for(let i=0;i<4;i++)poly(c,[[-13+i*8,0],[-9+i*8,6],[-5+i*8,0]],'#f0dbb1');ellipse(c,-8,-7,2,2,'#f2d899');ellipse(c,8,-7,2,2,'#f2d899');}else{line(c,[[0,-27],[0,-19]],'#e9d193',2);line(c,[[-4,-23],[4,-23]],'#e9d193',2);}}
    if(kind==='bench'){rr(c,-22,-12,44,12,3,'#9b7b52');rr(c,-24,2,48,10,3,'#b49569');rr(c,-19,11,5,11,1,'#785b3b');rr(c,14,11,5,11,1,'#785b3b');line(c,[[-17,-7],[-17,7]],'#cfb582',3);line(c,[[17,-7],[17,7]],'#cfb582',3);}
    if(kind==='remove'){line(c,[[-16,-14],[16,17]],'#caac8b',6);line(c,[[16,-14],[-16,17]],'#caac8b',6);}
    c.restore();
  }
  function drawDebris(c,kind,x,y,t){c.save();c.translate(x,y);ellipse(c,0,12,21,7,'#00000028');
    if(kind==='rubble'){poly(c,[[-22,9],[-15,-8],[-3,-5],[3,10]],'#6b7e79');poly(c,[[0,10],[3,-17],[16,-13],[24,8]],'#81918a');poly(c,[[3,-17],[16,-13],[9,-6]],'#a5aea0');poly(c,[[-13,17],[-7,6],[3,9],[7,17]],'#546964');}
    if(kind==='sword'){line(c,[[-12,18],[11,-13]],'#374b4c',7);poly(c,[[-9,8],[6,-17],[13,-22],[13,-12],[-3,13]],'#becdd1');line(c,[[-13,4],[2,14]],'#d6b574',4);line(c,[[-10,12],[-17,22]],'#9e7954',5);}
    if(kind==='spill'){ellipse(c,0,8,23,11,'#476f5d');ellipse(c,-3,4,18,8,'#75a176');ellipse(c,9,-2,4,3,'#a5c78b');ellipse(c,-21,17,4,2,'#83a77b');}
    if(kind==='wood'){c.rotate(-.3);rr(c,-21,-4,43,10,1,'#947957');c.rotate(.7);rr(c,-21,2,35,10,1,'#b3976b');line(c,[[-13,6],[9,6]],'#7e6548',1.5);}
    c.globalAlpha=.45+Math.sin(t*2+x)*.25;line(c,[[16,-24],[16,-16]],'#e4cd8c',2);line(c,[[12,-20],[20,-20]],'#e4cd8c',2);c.restore();}
  function character(c,x,y,color,walk,t,isWorker=false){c.save();c.translate(x,y);ellipse(c,0,14,14,5,'#04151670');const bob=walk?Math.sin(t*12)*2:Math.sin(t*2)*.5;c.translate(0,bob);rr(c,-8,7,6,10,2,'#ab916d');rr(c,3,7,6,10,2,'#ab916d');poly(c,[[-10,-11],[9,-11],[14,9],[-13,9]],color);rr(c,-8,-25,16,17,5,'#ddbc8b');if(isWorker){poly(c,[[-13,-20],[-6,-32],[5,-30],[13,-19]],'#83a27a');line(c,[[13,6],[26,-22]],'#c5a376',3);poly(c,[[12,-1],[23,5],[14,23],[3,16]],'#dac48b');}else{rr(c,-10,-28,20,9,3,'#a5b8b5');rr(c,-4,-32,7,5,1,color);line(c,[[14,9],[17,-15]],'#c6d2c9',3);line(c,[[11,1],[19,2]],'#e1bd7b',3);}rr(c,-4,-18,2,3,0,'#293c36');rr(c,3,-18,2,3,0,'#293c36');c.restore();}
  function torch(x,y,t){ctx.save();ctx.translate(x,y);const glow=ctx.createRadialGradient(0,-14,2,0,-14,70);glow.addColorStop(0,'#e6ac5835');glow.addColorStop(1,'#e6ac5800');ctx.fillStyle=glow;ctx.fillRect(-72,-86,144,144);rr(ctx,-4,-4,8,16,1,'#83745a');ellipse(ctx,0,-14,6+Math.sin(t*8)*1.4,12,'#d4a258');ellipse(ctx,0,-13,3,7,'#f7db9a');ctx.restore();}
  function render(t,dt){ctx.clearRect(0,0,1080,600);ctx.fillStyle=game.phase==='night'?'#0d1b24':'#112329';ctx.fillRect(0,0,1080,600);
    // Hand-drawn stonework, vegetation and objects, generated entirely from primitives.
    for(let i=0;i<80;i++){const x=(i*173+23)%1080,y=(i*97+17)%600;ctx.globalAlpha=.18;ellipse(ctx,x,y,1+(i%3),1,'#8bada1');}ctx.globalAlpha=1;
    for(let y=0;y<10;y++)for(let x=0;x<18;x++){
      if(!C.floor(x,y))continue;const [px,py]=pos(x,y),alt=(x*7+y*3)%4;
      rr(ctx,px-26,py-25,52,56,2,'#0b1b1e');rr(ctx,px-26,py-25,52,49,2,['#33494a','#354d4b','#304647','#3a504d'][alt],'#425a54');
      line(ctx,[[px-23,py-21],[px+21,py-21]],'#57706355',1);line(ctx,[[px-22,py+20],[px+21,py+20]],'#152d3355',1);
      if((x+y)%3===0)line(ctx,[[px-19,py+4],[px-8,py+7],[px-10,py+13]],'#243c3d',1);
      if(!C.floor(x,y-1)){rr(ctx,px-28,py-49,56,25,2,'#445a55','#182b2e');rr(ctx,px-26,py-49,52,8,1,'#617366');line(ctx,[[px+(x%2?8:-7),py-40],[px+(x%2?8:-7),py-25]],'#263b3b',2);}
      if(!C.floor(x-1,y)){rr(ctx,px-34,py-27,9,53,2,'#465e54');line(ctx,[[px-33,py-26],[px-33,py+22]],'#6b7e6a',1);}
      if(!C.floor(x+1,y)){rr(ctx,px+26,py-27,9,53,2,'#304943');line(ctx,[[px+27,py-26],[px+27,py+22]],'#647b66',1);}
      if(!C.floor(x,y+1)){rr(ctx,px-26,py+24,52,15,2,'#203637','#14282d');rr(ctx,px-26,py+24,52,4,1,'#5a6f5e');}
    }
    // Discreet moss at room corners.
    [[1,2],[5,6],[7,1],[11,4],[12,8],[16,4]].forEach(([x,y],j)=>{const[p,q]=pos(x,y);for(let i=0;i<5;i++)ellipse(ctx,p-18+i*4,q+14+Math.sin(i)*4,4,2,['#6c8557','#8e995a','#536f55'][(i+j)%3]);});
    ctx.save();ctx.setLineDash([2,9]);ctx.strokeStyle='#b4c7a845';ctx.lineWidth=2;ctx.lineCap='round';ctx.beginPath();C.ROUTE.forEach((p,i)=>{const v=pos(...p);i?ctx.lineTo(...v):ctx.moveTo(...v);});ctx.stroke();ctx.restore();
    const [enx,eny]=pos(...C.ROUTE[0]),[exx,exy]=pos(...C.ROUTE.at(-1));
    rr(ctx,enx-20,eny-33,29,55,4,'#244e47','#6d9e81');line(ctx,[[enx-13,eny],[enx+4,eny]],'#afd4ac',2);line(ctx,[[enx-2,eny-6],[enx+5,eny],[enx-2,eny+6]],'#afd4ac',2);
    rr(ctx,exx-10,exy-32,28,55,4,'#575238','#ab9e66');line(ctx,[[exx-4,exy],[exx+11,exy]],'#e4ca84',2);line(ctx,[[exx+5,exy-5],[exx+11,exy],[exx+5,exy+5]],'#e4ca84',2);
    ctx.font='10px "Yu Gothic UI",sans-serif';ctx.textAlign='center';ctx.fillStyle='#a6c1ad';ctx.fillText('入口',enx,eny+45);ctx.fillStyle='#ccb47d';ctx.fillText('出口',exx,exy+45);
    [[2,2],[8,1],[14,4]].forEach(([x,y])=>{const [px,py]=pos(x,y);torch(px,py-32,t);});
    if(hover&&game.phase==='prep'&&active&&$('modalBackdrop').hidden){const[px,py]=pos(...hover);if(C.floor(...hover)){const valid=!C.inspect(game,...hover,tool);rr(ctx,px-25,py-24,50,47,3,valid?'#b7d6a72c':'#e3a38318',valid?'#beddaa':'#ce9679');if(valid&&!['broom','remove'].includes(tool)){ctx.save();ctx.globalAlpha=.6;ctx.translate(px,py);drawIcon(ctx,tool,.8,t);ctx.restore();}}}
    const renderables=[];Object.entries(game.debris).forEach(([k,kind])=>{const[x,y]=k.split(',').map(Number);renderables.push({order:y*52,fn:()=>drawDebris(ctx,kind,...pos(x,y),t)});});
    Object.entries(game.devices).forEach(([k,kind])=>{const[x,y]=k.split(',').map(Number);renderables.push({order:y*52,fn:()=>{ctx.save();ctx.translate(...pos(x,y));drawIcon(ctx,kind,.85,t);ctx.restore();}});});
    if(game.phase!=='night'){worker.x+=(worker.tx-worker.x)*Math.min(1,dt*6);worker.y+=(worker.ty-worker.y)*Math.min(1,dt*6);renderables.push({order:worker.y*52+12,fn:()=>{const[p,q]=pos(worker.x,worker.y);character(ctx,p+16,q+10,'#87b18f',Math.abs(worker.tx-worker.x)>.05,t,true);}});}
    const bubbles=[];
    if(game.phase==='night')for(const h of game.heroes){if(h.pos<0||h.done)continue;const n=Math.floor(h.pos),p=C.ROUTE[Math.min(n,C.ROUTE.length-1)],q=C.ROUTE[Math.min(n+1,C.ROUTE.length-1)],v=h.pos-n,[px,py]=pos(p[0]+(q[0]-p[0])*v,p[1]+(q[1]-p[1])*v);renderables.push({order:py-58+18,fn:()=>{character(ctx,px,py,['#82adbb','#b99bc1','#d1aa6e','#9fb38c'][h.id],!paused,t);rr(ctx,px-17,py-41,34,4,2,'#17292b');rr(ctx,px-17,py-41,34*h.hp/h.maxHp,4,2,h.hp/h.maxHp<.3?'#e8a18c':'#aed9a8');}});if(h.bubbleUntil>game.elapsed)bubbles.push({px,py,text:h.bubble});}
    renderables.sort((a,b)=>a.order-b.order).forEach(o=>o.fn());
    for(const b of bubbles){ctx.font='11px "Yu Gothic UI",sans-serif';const w=ctx.measureText(b.text).width+18,px=Math.min(1080-w-5,Math.max(5,b.px-w/2));rr(ctx,px,b.py-72,w,22,5,'#e4e5ca');ctx.fillStyle='#284238';ctx.textAlign='left';ctx.fillText(b.text,px+9,b.py-57);}
    particles=particles.filter(p=>p.life>0);for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=90*dt;ctx.globalAlpha=Math.max(0,Math.min(1,p.life*2));rr(ctx,p.x,p.y,3,3,1,p.color);}ctx.globalAlpha=1;
    // Calm greenery and stones outside the playable rooms.
    [[120,490],[385,425],[730,152],[920,515],[605,425]].forEach(([x,y],i)=>{ellipse(ctx,x,y+7,18,5,'#081b2055');line(ctx,[[x,y+8],[x-4,y-15]],'#6c885c',2);poly(ctx,[[x-3,y],[x-17,y-9],[x-14,y-15],[x-3,y-8]],'#53765b');poly(ctx,[[x-2,y-8],[x+12,y-22],[x+14,y-12],[x-1,y-3]],'#6d875f');if(i%2===0){ellipse(ctx,x+20,y+4,10,6,'#657468');ellipse(ctx,x+18,y+1,7,3,'#889080');}});
    if(paused&&game.phase==='night'){ctx.fillStyle='#10232c55';ctx.fillRect(0,0,1080,600);ctx.font='600 21px "Yu Gothic UI",sans-serif';ctx.textAlign='center';ctx.fillStyle='#e5ead8';ctx.fillText('一時停止中',540,310);}
  }
  function frame(now){const dt=Math.min(.05,(now-frameTime)/1000||.016);frameTime=now;if(active&&game.phase==='night'&&!paused&&$('modalBackdrop').hidden&&!document.hidden){for(let i=0;i<speed;i++)C.tick(game,dt);if(game.phase==='report'){save();update();report();}else if(now-lastUI>160){updateNight();lastUI=now;}}render(now/1000,dt);requestAnimationFrame(frame);}
  update();welcome();requestAnimationFrame(frame);
})();
